                    Location location = new Location(row, col);
                    Shark shark = new Shark(true, field, location);
                    creatures.add(shark);
                }else if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Whale whale = new Whale(true, field, location);
                    creatures.add(whale);
